-- ROOFING/EXTERIORS - Final Invoice & Warranty Card
--
-- A final-draw billing document plus a manufacturer warranty card: contractor
-- info with a linked billing email, an invoice-meta key/value table, a
-- "Bill To" block, a 5-column scope & costs table (5 line items followed by
-- SUBTOTAL / Change Orders / Sales Tax / Total Contract / Less Deposits /
-- AMOUNT DUE rows -- only the subtotal and final amount-due rows are bold,
-- matching the reference's accounting convention of bolding only the two
-- "key" totals), a green $ Payment Request line, three captioned 3-photo
-- proof-of-completion groups, a Warranty Card table (with a pre-filled
-- "10 yrs (contractor)" workmanship-warranty example, matching the
-- reference), a Snippets terms placeholder ("[INSERT SNIPPET]"), and an
-- owner/PM sign-off. No merge tokens -- every field is hand-filled per job,
-- matching the rest of the working-document family.
INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'example-roofing-final-invoice-warranty-card',
  NULL,
  NULL,
  'ROOFING/EXTERIORS - Final Invoice & Warranty Card',
  jsonb_build_object(
    'style', 'report',
    'description', 'Final-draw invoice with scope & costs, payment request, photo proof of completion, and a manufacturer warranty card.',
    'html', $html$<h1>ROOFING/EXTERIORS - Final Invoice &amp; Warranty Card</h1><p><strong>Contractor Information</strong></p><p><strong>[Your Roofing Co.]</strong> &middot; <strong>Phone</strong> [###-###-####] &middot; <strong>Email</strong> [<a href="mailto:billing@company.com">billing@company.com</a>]</p><p>State Roofing License #: [####] | Manufacturer Cert: [Platinum / Master Elite]</p><table><tbody><tr><th><p>Invoice #</p></th><td><p>[####]</p></td></tr><tr><th><p>Invoice Date</p></th><td><p>[MM/DD/YY]</p></td></tr><tr><th><p>Project</p></th><td><p>[Address]</p></td></tr><tr><th><p>Contract #</p></th><td><p>[####]</p></td></tr></tbody></table><hr><p><strong>Bill To:</strong></p><p>[Owner / Property Manager]</p><p>[Address]</p><p>Contact: [Name] &middot; Phone [###-###-####]</p><hr><h2>Scope &amp; Costs &ndash; Final Draw</h2><table><tbody><tr><th><p>Line</p></th><th><p>Description</p></th><th><p>Squares / Qty</p></th><th><p>Unit $</p></th><th><p>Total $</p></th></tr><tr><td><p>001</p></td><td><p>Tear-off existing layers</p></td><td><p>28 sq</p></td><td><p>$</p></td><td><p>$</p></td></tr><tr><td><p>002</p></td><td><p>Install underlayment</p></td><td><p>28 sq</p></td><td><p>$</p></td><td><p>$</p></td></tr><tr><td><p>003</p></td><td><p>Install laminated shingles (ASTM D3462)</p></td><td><p>28 sq</p></td><td><p>$</p></td><td><p>$</p></td></tr><tr><td><p>004</p></td><td><p>Flashings / pipe boots</p></td><td><p>&mdash;</p></td><td><p>$</p></td><td><p>$</p></td></tr><tr><td><p>005</p></td><td><p>Cleanup &amp; haul-off</p></td><td><p>&mdash;</p></td><td><p>$</p></td><td><p>$</p></td></tr><tr><td><p><strong>SUBTOTAL</strong></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p><strong>[Subtotal]</strong></p></td></tr><tr><td><p>Change Orders</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p>[CO Total]</p></td></tr><tr><td><p>Sales Tax (X %)</p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p>[Tax]</p></td></tr><tr><td><p>Total Contrac